import pytest
from candidate import filter_integers

class TestFilterIntegers:
    @pytest.mark.parametrize("values, expected", [
        (['a', 3.14, 5], [5]),
        ([1, 2, 3, 'abc', {}, []], [1, 2, 3]),
        ([1, 'abc', 3.14, {}], [1, 3]),
        ([None, 1, 2, '3', 3.14, []], [1, 2]),
        ([1, 'a', None, 2], [1, 2]),
        ([1, 'a', None, 2, 3.14], [1, 2]),
        ([], []),
        ([1, 2, 'a', None], [1, 2]),
        ([1.0, 2.5, '3', 'four'], []),
    ])
    def test_filter_integers(self, values, expected):
        assert filter_integers(values) == expected

    @pytest.mark.parametrize("values, expected", [
        (None, []),
        ("", []),
        ([None], []),
        ([None, 'a', 1], []),
    ])
    def test_filter_integers_none_and_empty(self, values, expected):
        assert filter_integers(values) == expected

    def test_filter_integers_type_error(self):
        with pytest.raises(TypeError):
            filter_integers("not a list")

    @pytest.mark.parametrize("values, expected", [
        ([1, 2, 'a', None], [1, 2]),
        ([1.0, 2.5, 'three', 'four'], []),
    ])
    def test_filter_integers_no_type_error(self, values, expected):
        assert filter_integers(values) == expected

    @pytest.mark.parametrize("values, expected", [
        ([1, 2, 'a', None, 3.14], [1, 2, None]),
    ])
    def test_filter_integers_mixed_types(self, values, expected):
        assert filter_integers(values) == expected

    @pytest.mark.parametrize("values", [[], [None], ["", 0], [0], [1, 2, 3.14, "a"]], ids=["empty", "None", "empty_string", "zero", "non_int"])
    def test_filter_integers_edge_cases(self, values):
        assert filter_integers(values) == []

    @pytest.mark.parametrize("values", [1, "1", 1.0, None, True, "True", 1+2j, (1,2)], ids=["int", "str", "float", "None", "bool", "complex", "tuple"])
    def test_filter_integers_non_int(self, values):
        assert filter_integers([values]) == []

    @pytest.mark.parametrize("values", [1, 2, 3], ids=["valid_int"])
    def test_filter_integers_valid_int(self, values):
        assert filter_integers([values]) == [values]

